// ─── AVAILABILITY PAGE ────────────────────────────────────────────────────────
function AvailabilityPage({ bookings, loading, openBooking }) {
  const [selDate, setSelDate] = useState(TODAY);

  function changeDate(d) {
    const dt = new Date(selDate + "T00:00:00");
    dt.setDate(dt.getDate() + d);
    setSelDate(dt.toISOString().split("T")[0]);
  }

  return (
    <div className="page">
      <div className="page-inner">
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:"1rem",marginBottom:"1.5rem"}}>
          <div>
            <div className="page-title">Court Availability</div>
            <div className="page-sub">Tap any green slot to book. Updates in real-time.</div>
          </div>
          <div className="live-badge"><span className="ld"/>Live</div>
        </div>

        <div className="date-bar">
          <div style={{display:"flex",gap:".4rem"}}>
            <button className="date-nav-btn" onClick={() => changeDate(-1)}>←</button>
            <button className="date-nav-btn" onClick={() => changeDate(1)}>→</button>
          </div>
          <input type="date" className="date-inp" value={selDate} min={TODAY}
            onChange={(e) => setSelDate(e.target.value)} />
          <span className="date-label">{formatDate(selDate)}</span>
        </div>

        <div className="legend">
          {[["#16a34a","Available — tap to book"],["#ef4444","Reserved"],["#f59e0b","Ongoing"],["#d1d5db","Closed"]].map(([c,l]) => (
            <div className="legend-item" key={l}><div className="legend-dot" style={{background:c}}/>{l}</div>
          ))}
        </div>

        <div className="avail-wrap">
          {loading ? <Spinner text="Loading schedule..." /> : (
            <table className="avail-tbl">
              <thead>
                <tr>
                  <th>Time</th>
                  {COURTS.map((c) => <th key={c}>{c}</th>)}
                </tr>
              </thead>
              <tbody>
                {HOURS.map((h) => (
                  <tr key={h}>
                    <td className="tc">{fmt(h)}</td>
                    {COURTS.map((court) => {
                      const st = getSlotStatus(bookings, selDate, court, h);
                      return (
                        <td key={court}>
                          <button className={`slot slot-${st}`}
                            disabled={st !== "available"}
                            onClick={() => openBooking(court, selDate, h)}>
                            <span className="sd"/>
                            {st === "available" ? "Open" : st === "reserved" ? "Reserved" : "Ongoing"}
                          </button>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── BOOKING TABLE ────────────────────────────────────────────────────────────
function BookingTable({ bookings, loading, onCancel, onOngoing, onReserved, showDate }) {
  if (loading) return <Spinner text="Loading bookings..." />;
  if (!bookings.length) return (
    <div style={{padding:"3rem",textAlign:"center",color:"var(--g6)"}}>
      <div style={{fontSize:"2.5rem",marginBottom:".75rem"}}>📭</div>
      <div style={{fontWeight:600}}>No bookings found</div>
    </div>
  );
  return (
    <div style={{overflowX:"auto"}}>
      <table className="bt">
        <thead>
          <tr>
            {showDate && <th>Date</th>}
            <th>Court</th><th>Start</th><th>End</th><th>Hrs</th>
            <th>Name</th><th>Phone</th><th>Status</th><th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {[...bookings].sort((a,b) => a.startHour - b.startHour).map((b) => (
            <tr key={b.id}>
              {showDate && <td>{b.date}</td>}
              <td><strong>{b.court}</strong></td>
              <td style={{whiteSpace:"nowrap"}}>{fmt(b.startHour)}</td>
              <td style={{whiteSpace:"nowrap"}}>{fmt(b.endHour)}</td>
              <td><span className="badge badge-n">{calcHours(b.startHour,b.endHour)}h</span></td>
              <td>{b.name}</td>
              <td>{b.phone}</td>
              <td>
                <span className={`badge badge-${b.status==="reserved"?"r":b.status==="ongoing"?"y":"n"}`}>
                  {b.status}
                </span>
              </td>
              <td>
                <div className="tbl-actions">
                  {b.status === "reserved" && <button className="btn-warn" onClick={() => onOngoing(b.id)}>▶ Start</button>}
                  {b.status === "ongoing" && <button className="btn-secondary" style={{fontSize:".78rem",padding:".4rem .8rem"}} onClick={() => onReserved(b.id)}>↩ Reset</button>}
                  <button className="btn-danger" onClick={() => onCancel(b.id)}>✕ Cancel</button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}


// ─── ADMIN LOGIN ──────────────────────────────────────────────────────────────
function AdminLogin({ onSuccess }) {
  const [pw, setPw] = useState("");
  const [error, setError] = useState("");
  const [shake, setShake] = useState(false);

  function handleLogin() {
    if (pw === "bnjadmin") {
      sessionStorage.setItem("bnj_admin_auth", "1");
      onSuccess();
    } else {
      setError("Incorrect password. Please try again.");
      setShake(true);
      setPw("");
      setTimeout(() => setShake(false), 600);
    }
  }

  return (
    <div style={{minHeight:"calc(100vh - 68px)",display:"flex",alignItems:"center",justifyContent:"center",background:"var(--bg)",padding:"2rem"}}>
      <div style={{background:"white",border:"1px solid var(--g8)",borderRadius:"var(--rx)",padding:"2.5rem 2rem",width:"100%",maxWidth:"380px",boxShadow:"var(--s3)",animation:shake?"shakeIt .5s ease":"none"}}>
        <style>{`@keyframes shakeIt{0%,100%{transform:translateX(0)}20%,60%{transform:translateX(-8px)}40%,80%{transform:translateX(8px)}}`}</style>
        <div style={{textAlign:"center",marginBottom:"2rem"}}>
          <div style={{width:64,height:64,background:"var(--g1)",borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",fontSize:"1.75rem",margin:"0 auto .75rem"}}>🔐</div>
          <div style={{fontWeight:800,fontSize:"1.25rem",color:"var(--g1)",marginBottom:".25rem"}}>Admin Access</div>
          <div style={{fontSize:".875rem",color:"var(--g5)"}}>Enter your admin password to continue</div>
        </div>
        <div style={{marginBottom:"1rem"}}>
          <label style={{display:"block",fontSize:".72rem",fontWeight:700,color:"var(--g4)",marginBottom:".35rem",textTransform:"uppercase",letterSpacing:".06em"}}>Password</label>
          <input
            className="fi"
            type="password"
            placeholder="Enter admin password"
            value={pw}
            onChange={(e) => { setPw(e.target.value); setError(""); }}
            onKeyDown={(e) => e.key === "Enter" && handleLogin()}
            autoFocus
          />
          {error && <div style={{fontSize:".8rem",color:"#b91c1c",marginTop:".4rem",display:"flex",alignItems:"center",gap:".3rem"}}>⚠ {error}</div>}
        </div>
        <button className="btn-primary" style={{width:"100%",justifyContent:"center"}} onClick={handleLogin}>
          Unlock Dashboard
        </button>
      </div>
    </div>
  );
}

// ─── ADMIN PAGE ───────────────────────────────────────────────────────────────
function AdminPage({ bookings, loading, setBookings, addToast }) {
  const [tab, setTab] = useState("dashboard");
  const [filterDate, setFilterDate] = useState(TODAY);

  const todayB = bookings.filter((b) => b.date === TODAY);
  const weekB = bookings.filter((b) => {
    const diff = (new Date(b.date + "T00:00:00") - new Date()) / 86400000;
    return diff >= -1 && diff <= 6;
  });
  const totalHrs = bookings.reduce((a, b) => a + calcHours(b.startHour, b.endHour), 0);
  const totalRev = bookings.reduce((a, b) => a + calcHours(b.startHour, b.endHour) * 150, 0);

  async function cancelBooking(id) {
    if (!confirm("Cancel this booking?")) return;
    try {
      await deleteBooking(id);
      setBookings((p) => p.filter((b) => b.id !== id));
      addToast("Booking cancelled", "success");
    } catch { addToast("Failed to cancel", "error"); }
  }
  async function markOngoing(id) {
    try {
      const u = await updateBookingStatus(id, "ongoing");
      setBookings((p) => p.map((b) => b.id === id ? u : b));
      addToast("Marked as ongoing", "success");
    } catch { addToast("Failed to update", "error"); }
  }
  async function markReserved(id) {
    try {
      const u = await updateBookingStatus(id, "reserved");
      setBookings((p) => p.map((b) => b.id === id ? u : b));
      addToast("Status reset", "success");
    } catch { addToast("Failed to update", "error"); }
  }

  const filteredB = tab === "daily" ? bookings.filter((b) => b.date === filterDate)
    : tab === "weekly" ? weekB : bookings;

  const TABS = [
    {id:"dashboard",label:"Dashboard",icon:"📊"},
    {id:"daily",label:"Daily View",icon:"📅"},
    {id:"weekly",label:"Weekly",icon:"📆"},
    {id:"all",label:"All Bookings",icon:"📋"},
  ];

  return (
    <div className="admin-wrap">
      <div className="sidebar">
        <img src={LOGO_URI} alt="BNJ Pickle Yard" className="sidebar-logo"/>
        <div style={{fontWeight:600,fontSize:".78rem",color:"rgba(255,255,255,.3)",padding:"0 .65rem",marginBottom:"1rem"}}>Admin Panel</div>
        <div className="sidebar-section">Navigation</div>
        {TABS.map((t) => (
          <button key={t.id} className={`sab ${tab===t.id?"on":""}`} onClick={() => setTab(t.id)}>
            <span>{t.icon}</span>{t.label}
          </button>
        ))}
        <div style={{marginTop:"auto",paddingTop:"1.5rem"}}>
          <button className="sab" style={{color:"rgba(239,68,68,.7)",marginTop:".5rem"}}
            onClick={() => { sessionStorage.removeItem("bnj_admin_auth"); window.location.reload(); }}>
            <span>🔓</span>Logout
          </button>
        </div>
      </div>

      <div className="admin-main">
        {tab === "dashboard" && (
          <>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"1.5rem",flexWrap:"wrap",gap:"1rem"}}>
              <div>
                <div className="page-title">Dashboard</div>
                <div className="page-sub">{formatDate(TODAY)}</div>
              </div>
              <div className="live-badge"><span className="ld"/>Live Data</div>
            </div>
            <div className="stat-grid">
              {[
                {label:"Total Bookings",val:loading?"…":bookings.length,sub:"All time"},
                {label:"Today",val:loading?"…":todayB.length,sub:"Scheduled today"},
                {label:"Ongoing",val:loading?"…":bookings.filter(b=>b.status==="ongoing").length,sub:"Currently playing"},
                {label:"Total Revenue",val:loading?"…":`₱${totalRev.toLocaleString()}`,sub:"Estimated"},
              ].map((s) => (
                <div className="stat-card" key={s.label}>
                  <div className="stat-label">{s.label}</div>
                  <div className="stat-val">{s.val}</div>
                  <div className="stat-sub">{s.sub}</div>
                </div>
              ))}
            </div>
            <div className="tbl-wrap">
              <div className="tbl-head">
                <div className="tbl-title">Today's Bookings</div>
                <span className="badge badge-g">{todayB.length} bookings</span>
              </div>
              <BookingTable bookings={todayB} loading={loading} onCancel={cancelBooking} onOngoing={markOngoing} onReserved={markReserved}/>
            </div>
          </>
        )}
        {(tab==="daily"||tab==="weekly"||tab==="all") && (
          <>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"1.5rem",flexWrap:"wrap",gap:".75rem"}}>
              <div>
                <div className="page-title">{tab==="daily"?"Daily View":tab==="weekly"?"Weekly Schedule":"All Bookings"}</div>
                <div className="page-sub">{filteredB.length} booking{filteredB.length!==1?"s":""}</div>
              </div>
              {tab==="daily" && <input type="date" className="date-inp" value={filterDate} onChange={(e) => setFilterDate(e.target.value)}/>}
            </div>
            <div className="tbl-wrap">
              <BookingTable bookings={filteredB} loading={loading} onCancel={cancelBooking} onOngoing={markOngoing} onReserved={markReserved} showDate/>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// ─── ROOT APP ─────────────────────────────────────────────────────────────────
export default function App() {
  const [page, setPage] = useState("home");
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState("");
  const [bookingModal, setBookingModal] = useState(null);
  const [dark, setDark] = useState(false);
  const [toasts, setToasts] = useState([]);
  const [mobileNav, setMobileNav] = useState(false);
  const [adminAuth, setAdminAuth] = useState(() => sessionStorage.getItem("bnj_admin_auth") === "1");

  useEffect(() => { loadBookings(); }, []);

  useEffect(() => {
    const ch = subscribeToBookings((payload) => {
      if (payload.eventType === "INSERT") {
        const n = { id:payload.new.id, court:payload.new.court, date:payload.new.date,
          startHour:payload.new.start_hour, endHour:payload.new.end_hour,
          name:payload.new.name, phone:payload.new.phone, status:payload.new.status };
        setBookings((p) => [...p.filter(b => b.id !== n.id), n]);
      } else if (payload.eventType === "UPDATE") {
        setBookings((p) => p.map((b) => b.id === payload.new.id ? {...b, status:payload.new.status} : b));
      } else if (payload.eventType === "DELETE") {
        setBookings((p) => p.filter((b) => b.id !== payload.old.id));
      }
    });
    return () => { ch.unsubscribe(); };
  }, []);

  useEffect(() => { document.body.className = dark ? "dark" : ""; }, [dark]);

  async function loadBookings() {
    setLoading(true); setDbError("");
    try { setBookings(await fetchBookings()); }
    catch (err) { setDbError("Could not connect to database. Check your Supabase credentials."); }
    finally { setLoading(false); }
  }

  function addToast(msg, type = "success") {
    const id = Date.now();
    setToasts((p) => [...p, {id, message:msg, type}]);
    setTimeout(() => setToasts((p) => p.filter((t) => t.id !== id)), 3500);
  }

  function openBooking(court, date, hour) {
    setBookingModal({ court: typeof court === "string" ? court : COURTS[0], date: date || TODAY, hour: hour ?? 9 });
  }

  async function handleConfirm(data) {
    const saved = await createBooking(data);
    setBookings((p) => [...p, saved]);
    addToast(`${data.court} booked: ${fmt(data.startHour)} – ${fmt(data.endHour)}`, "success");
    sendNotifications({ ...data, id: saved.id });
  }

  const NAV = [{id:"home",label:"Home"},{id:"availability",label:"Availability"},{id:"admin",label:"Admin"}];

  return (
    <>
      <style>{css}</style>
      <nav className={`nav ${mobileNav ? "mobile-open" : ""}`}>
        <div className="nav-logo" style={{cursor:"pointer"}} onClick={() => setPage("home")}>
          <img src={LOGO_URI} alt="BNJ Pickle Yard"/>
        </div>
        <div className="nav-links">
          {NAV.map((n) => (
            <button key={n.id} className={`nav-btn ${page===n.id?"active":""}`}
              onClick={() => { setPage(n.id); setMobileNav(false); }}>
              {n.label}
            </button>
          ))}
          <button className="nav-btn nav-cta" onClick={() => { openBooking(); setMobileNav(false); }}>Book Now</button>
          <button className="nav-btn" onClick={() => setDark((d) => !d)}>{dark ? "☀️" : "🌙"}</button>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:".5rem"}}>
          <button className="nav-btn" onClick={() => setDark((d) => !d)}>{dark ? "☀️" : "🌙"}</button>
          <button className="hamburger" onClick={() => setMobileNav((m) => !m)}>
            <span/><span/><span/>
          </button>
        </div>
      </nav>

      {dbError && (
        <div className="err-bar" style={{margin:"1rem 1.5rem",borderRadius:"var(--r)"}}>
          ⚠ {dbError}
          <button className="btn-secondary" style={{marginLeft:"auto",fontSize:".8rem",padding:".35rem .75rem"}} onClick={loadBookings}>Retry</button>
        </div>
      )}

      {page==="home" && <HomePage setPage={setPage} openBooking={openBooking} bookings={bookings}/>}
      {page==="availability" && <AvailabilityPage bookings={bookings} loading={loading} openBooking={openBooking}/>}
      {page==="admin" && (
        adminAuth
          ? <AdminPage bookings={bookings} loading={loading} setBookings={setBookings} addToast={addToast}/>
          : <AdminLogin onSuccess={() => setAdminAuth(true)} />
      )}

      {bookingModal && (
        <BookingModal slot={bookingModal} bookings={bookings}
          onClose={() => setBookingModal(null)} onConfirm={handleConfirm}/>
      )}

      <Toast toasts={toasts}/>

      <footer style={{background:"#0c0c0c",padding:"3rem 2rem",textAlign:"center"}}>
        <img src={LOGO_URI} alt="BNJ Pickle Yard" style={{height:70,marginBottom:"1.25rem",opacity:.9}}/>
        <div style={{color:"rgba(255,255,255,.4)",fontSize:".875rem",marginBottom:".4rem"}}>Mutia, Zamboanga del Norte · Open 6AM – 12AM Sunday to Friday</div>
        <div style={{color:"rgba(255,255,255,.2)",fontSize:".78rem"}}>© 2025 BNJ Pickle Yard. All rights reserved. · Est. 2025</div>
      </footer>
    </>
  );
}
